CREATE OR REPLACE FUNCTION public.freela_respond(_assignment_id uuid,_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; BEGIN SELECT * INTO a FROM public.freelance_assignments WHERE id=_assignment_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR a.professional_id IS DISTINCT FROM public.my_professional_id() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF a.status<>'convidado' THEN RAISE EXCEPTION 'Convite não está pendente'; END IF; UPDATE public.freelance_assignments SET status=CASE WHEN _accept THEN 'reservado'::public.assignment_status ELSE 'cancelado'::public.assignment_status END WHERE id=a.id; IF _accept THEN UPDATE public.freelance_opportunities SET status='confirmada' WHERE id=a.opportunity_id AND status='selecionados'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.freela_checkin(_assignment_id uuid,_lat double precision,_lng double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; BEGIN SELECT * INTO a FROM public.freelance_assignments WHERE id=_assignment_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR a.professional_id IS DISTINCT FROM public.my_professional_id() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF a.status<>'reservado' THEN RAISE EXCEPTION 'Check-in disponível somente para reservas'; END IF; UPDATE public.freelance_assignments SET status='em_execucao',checkin_at=now(),checkin_lat=_lat,checkin_lng=_lng WHERE id=a.id; UPDATE public.freelance_opportunities SET status='em_andamento' WHERE id=a.opportunity_id AND status NOT IN ('cancelada','concluida'); END $$;
CREATE OR REPLACE FUNCTION public.freela_checkout(_assignment_id uuid,_lat double precision,_lng double precision,_result text,_report text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; exe boolean; BEGIN SELECT * INTO a FROM public.freelance_assignments WHERE id=_assignment_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR a.professional_id IS DISTINCT FROM public.my_professional_id() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF a.status<>'em_execucao' THEN RAISE EXCEPTION 'Faça check-in antes do check-out'; END IF; IF NOT EXISTS(SELECT 1 FROM public.freelance_evidence WHERE assignment_id=a.id) THEN RAISE EXCEPTION 'Envie ao menos uma evidência'; END IF; exe:=CASE _result WHEN 'concluida' THEN true WHEN 'ruptura_total' THEN true WHEN 'nao_vende_confirmado' THEN true WHEN 'nao_vende_pendente' THEN false WHEN 'atividade_nao_minha' THEN false ELSE null END; IF exe IS NULL THEN RAISE EXCEPTION 'Resultado inválido'; END IF; UPDATE public.freelance_assignments SET status='aguardando_aprovacao',checkout_at=now(),checkout_lat=_lat,checkout_lng=_lng,execution_result=_result,executed=exe,report=_report WHERE id=a.id; END $$;
CREATE OR REPLACE FUNCTION public.prevent_availability_overlap() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.professionals WHERE id=NEW.professional_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.availability a WHERE a.professional_id=NEW.professional_id AND a.weekday=NEW.weekday AND a.id<>NEW.id AND a.start_time<NEW.end_time AND NEW.start_time<a.end_time) THEN RAISE EXCEPTION 'Conflito de agenda neste dia'; END IF; IF NEW.kind='fixo' AND EXISTS(SELECT 1 FROM public.freelance_assignments a CROSS JOIN LATERAL generate_series((a.starts_at AT TIME ZONE 'America/Sao_Paulo')::date,(a.ends_at AT TIME ZONE 'America/Sao_Paulo')::date,interval '1 day') d WHERE a.professional_id=NEW.professional_id AND a.status NOT IN ('cancelado','reprovado','convidado') AND extract(dow FROM d)::int=NEW.weekday AND ((d::date+NEW.start_time) AT TIME ZONE 'America/Sao_Paulo')<a.ends_at AND a.starts_at<((d::date+NEW.end_time) AT TIME ZONE 'America/Sao_Paulo')) THEN RAISE EXCEPTION 'Conflito com reserva freelancer'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.protect_professional_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Titular não pode ser alterado'; END IF; IF pg_trigger_depth()=1 AND auth.uid() IS NOT NULL AND (NEW.rating_avg IS DISTINCT FROM OLD.rating_avg OR NEW.rating_count IS DISTINCT FROM OLD.rating_count) THEN RAISE EXCEPTION 'Avaliação é calculada pelo sistema'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_professional_identity BEFORE UPDATE ON public.professionals FOR EACH ROW EXECUTE FUNCTION public.protect_professional_identity();
CREATE OR REPLACE FUNCTION public.guard_company_membership() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.role NOT IN ('empresa','gestor_empresa') THEN RAISE EXCEPTION 'Papel inválido para vínculo empresarial'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_company_membership BEFORE INSERT OR UPDATE ON public.company_users FOR EACH ROW EXECUTE FUNCTION public.guard_company_membership();
REVOKE ALL ON FUNCTION public.freela_respond(uuid,boolean),public.freela_checkin(uuid,double precision,double precision),public.freela_checkout(uuid,double precision,double precision,text,text),public.select_freelancer(uuid),public.create_company(text,text,text,text),public.become_professional() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.freela_respond(uuid,boolean),public.freela_checkin(uuid,double precision,double precision),public.freela_checkout(uuid,double precision,double precision,text,text),public.select_freelancer(uuid),public.create_company(text,text,text,text),public.become_professional() TO authenticated;
CREATE POLICY "staff freelance updates" ON public.freelance_applications FOR UPDATE TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY "staff reviews" ON public.freelance_reviews FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()) AND reviewer_id=auth.uid());